css:
.fx-baw{width:min(680px,100%)}
.fx-baw .box{height:min(70vh,440px);overflow:auto;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface)}
.fx-baw .track{height:230%;position:relative}
.fx-baw .pin{position:sticky;top:0;height:min(70vh,440px);display:grid;place-items:center;padding:1.2em}
.fx-baw .cmp{position:relative;width:100%;aspect-ratio:16/10;border-radius:var(--radius);overflow:hidden;--p:0%}
.fx-baw .cmp>div{position:absolute;inset:0}
.fx-baw .cmp .bf{filter:grayscale(1) contrast(.85) brightness(.9)}
.fx-baw .cmp .af{clip-path:inset(0 calc(100% - var(--p)) 0 0)}
.fx-baw .cmp .fx-art{position:absolute;inset:0;border-radius:0}
.fx-baw .cmp .ln{position:absolute;top:0;bottom:0;left:var(--p);width:3px;background:var(--surface);box-shadow:0 0 0 1px color-mix(in srgb,#000 20%,transparent);z-index:2}
.fx-baw .cmp .ln::after{content:"↔";position:absolute;top:50%;left:50%;translate:-50% -50%;width:2.4em;height:2.4em;border-radius:50%;background:var(--surface);color:var(--text);display:grid;place-items:center;font-weight:700;box-shadow:0 2px 10px color-mix(in srgb,#000 25%,transparent)}
.fx-baw .tag{position:absolute;bottom:.8em;padding:.25em .8em;border-radius:99px;background:var(--surface);color:var(--text);font:700 .75em var(--font-body);letter-spacing:.1em;z-index:3}
.fx-baw .tag.l{left:.8em}.fx-baw .tag.r{right:.8em}
.fx-baw .hint{position:absolute;top:.8em;left:50%;translate:-50% 0;font-size:.8em;opacity:.6;z-index:4}
